//! The updater against a real(ish) feed: a loopback server serving a static
//! release manifest and an update artifact, the artifact signed with a
//! Tauri signing key generated by `pnpm tauri signer generate`, the check
//! and download driven through the plugin exactly as `updater.rs` drives
//! them (`updater_builder().pubkey(..).endpoints(..).build()` then `check`
//! and `download`).
//!
//! What this proves locally, per `tauri-plugin-updater`:
//!
//! - the endpoint template (`{{target}}/{{arch}}/{{current_version}}`, the
//!   shape scripts/release-config.mjs writes) resolves to the path this
//!   feed is shaped for,
//! - a static `platforms` manifest is looked up by `{os}-{arch}`,
//! - a newer release is offered, an older one is not,
//! - the artifact's minisign signature is verified against the configured
//!   public key during `download`, and tampered bytes or an artifact signed
//!   by another key are refused there.
//!
//! What it deliberately does not do: install. `install` hands the artifact
//! to the OS installer and (on Windows) exits the process, which is not a
//! thing a test can do; that pass happens with a real signed artifact at
//! release time -- README.md, "Release QA checklist". Tauri's mock runtime
//! carries no updater config, so the pubkey and endpoint are set on the
//! builder here the same way `tauri.release.json` sets them for the app.

use serde_json::json;
use std::sync::{Arc, Mutex};
use tauri::test::MockRuntime;
use tauri_plugin_updater::{Updater, UpdaterExt};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;

/// The fixture artifact's bytes: what the loopback feed serves and what a
/// successful download must return.
const ARTIFACT: &[u8] = b"matterwave test update artifact v1\n";

/// Public half of the test keypair, generated with
/// `pnpm tauri signer generate --ci -w test.key` (empty password), signing
/// this fixture's ARTIFACT with `pnpm tauri signer sign -f test.key
/// artifact.msi`. Test-only credentials, not the release key; the same two
/// commands regenerate both.
const TEST_PUBKEY: &str =
    "dW50cnVzdGVkIGNvbW1lbnQ6IG1pbmlzaWduIHB1YmxpYyBrZXk6IDA1RENCNzc1ODlCQjZDQ0UKUldUT2JMdUpkYmZjQldwelZuNCt6NDlJUHJtcXlwRExsUVVjQytUalRmN0Jycnpkak51bUVUVmsK";

/// The signature the fixture artifact's exact bytes verify against, from
/// the same keypair as TEST_PUBKEY.
const TEST_SIGNATURE: &str = "";

/// A valid signature of the same bytes by ANOTHER keypair -- a feed run by
/// a different publisher. The manifest carrying it is accepted (manifests
/// are plain JSON, unsigned); the artifact is what gets refused.
const OTHER_SIGNATURE: &str = "";

/// The release the manifest announces, the same one the release job
/// publishes (`MW_RELEASE` / tauri-action's latest.json).
const ANNOUNCED_VERSION: &str = "0.2.2";

/// The version Tauri's mock context reports: what `{{current_version}}`
/// becomes and what the release must be greater than.
const CURRENT_VERSION: &str = "0.1.0";

/// The os and arch halves the plugin reads the machine as.
fn os_name() -> &'static str {
    if cfg!(target_os = "windows") {
        "windows"
    } else if cfg!(target_os = "macos") {
        "darwin"
    } else {
        "linux"
    }
}

fn arch_name() -> &'static str {
    if cfg!(target_arch = "x86_64") {
        "x86_64"
    } else if cfg!(target_arch = "aarch64") {
        "aarch64"
    } else {
        "x86"
    }
}

/// `{os}-{arch}`, the fallback key of a static manifest.
fn platform_key() -> String {
    format!("{}-{}", os_name(), arch_name())
}

/// One feed: a manifest at
/// `/desktop/test/{os}/{arch}/{current_version}` -- the path the release
/// job's endpoint template resolves to -- and the artifact at
/// `/artifact`. The mutable fields are what the refusal tests flip.
struct Feed {
    base: String,
    requests: Arc<Mutex<Vec<String>>>,
    /// Served in place of ARTIFACT when set (the tampered-bytes case).
    artifact: Arc<Mutex<Vec<u8>>>,
    /// The signature the manifest announces.
    signature: Arc<Mutex<String>>,
    /// The version the manifest announces.
    version: Arc<Mutex<String>>,
}

impl Feed {
    async fn start() -> Arc<Self> {
        let listener = TcpListener::bind(("127.0.0.1", 0)).await.unwrap();
        let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
        let feed = Arc::new(Self {
            base,
            requests: Arc::new(Mutex::new(Vec::new())),
            artifact: Arc::new(Mutex::new(ARTIFACT.to_vec())),
            signature: Arc::new(Mutex::new(TEST_SIGNATURE.to_string())),
            version: Arc::new(Mutex::new(ANNOUNCED_VERSION.to_string())),
        });
        let serving = feed.clone();
        tokio::spawn(async move {
            while let Ok((sock, _)) = listener.accept().await {
                let feed = serving.clone();
                tokio::spawn(async move { feed.serve(sock).await });
            }
        });
        feed
    }

    /// The endpoint the release config's template names, this feed's way.
    fn endpoint(&self) -> String {
        format!(
            "{}/desktop/test/{{{{target}}}}/{{{{arch}}}}/{{{{current_version}}}}",
            self.base
        )
    }

    fn manifest(&self) -> serde_json::Value {
        // A static manifest as tauri-action publishes it: one entry per
        // platform. Here the `{os}-{arch}` key, which is the one the
        // lookup falls back to outside an installer.
        let url = format!("{}/artifact", self.base);
        let signature = self.signature.lock().unwrap().clone();
        json!({
            "version": self.version.lock().unwrap().clone(),
            "notes": "local fixture release",
            "pub_date": "2026-10-30T00:00:00Z",
            "platforms": {
                platform_key(): { "signature": signature, "url": url },
            }
        })
    }

    async fn serve(&self, mut sock: tokio::net::TcpStream) {
        let head = read_head(&mut sock).await;
        let target = head
            .lines()
            .next()
            .unwrap_or_default()
            .split_whitespace()
            .nth(1)
            .unwrap_or_default()
            .to_string();
        self.requests.lock().unwrap().push(target.clone());
        let body = if target.starts_with("/desktop/test/") {
            self.manifest().to_string().into_bytes()
        } else if target.starts_with("/artifact") {
            self.artifact.lock().unwrap().clone()
        } else {
            b"no such route".to_vec()
        };
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
            body.len()
        );
        let _ = sock.write_all(response.as_bytes()).await;
        let _ = sock.write_all(&body).await;
        let _ = sock.shutdown().await;
    }
}

async fn read_head(sock: &mut tokio::net::TcpStream) -> String {
    let mut buf = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        let n = sock.read(&mut chunk).await.unwrap_or(0);
        buf.extend_from_slice(&chunk[..n]);
        if let Some(end) = buf.windows(4).position(|w| w == b"\r\n\r\n") {
            return String::from_utf8_lossy(&buf[..end]).into_owned();
        }
        if n == 0 {
            return String::from_utf8_lossy(&buf).into_owned();
        }
    }
}

/// The app the plugin drives here: Tauri's mock runtime with the updater
/// plugin registered, the pubkey and endpoint set on the builder exactly
/// as `tauri.release.json` sets them for the built app. The app lives for
/// the test's scope; the updater's config is a copy it owns.
fn updater_on(app: &tauri::App<MockRuntime>, feed: &Feed) -> Updater {
    app.handle()
        .updater_builder()
        .pubkey(TEST_PUBKEY)
        .endpoints(vec![feed.endpoint().parse().unwrap()])
        .unwrap()
        .build()
        .unwrap()
}

fn mock_app() -> tauri::App<MockRuntime> {
    // The plugin reads its config from `plugins.updater`, which the mock
    // context does not carry; a stub (the pubkey is required in shape, the
    // builder below overrides it) is Config::default() in all that matters.
    let mut context = tauri::test::mock_context(tauri::test::noop_assets());
    context
        .config_mut()
        .plugins
        .0
        .insert("updater".to_string(), serde_json::json!({ "pubkey": "" }));
    tauri::test::mock_builder()
        .plugin(tauri_plugin_updater::Builder::new().build())
        .build(context)
        .unwrap()
}

fn requests_of(feed: &Feed) -> Vec<String> {
    feed.requests.lock().unwrap().clone()
}

#[tokio::test]
async fn a_newer_release_is_offered_and_its_artifact_verifies() {
    let feed = Feed::start().await;
    let app = mock_app();
    let updater = updater_on(&app, &feed);

    let update = updater.check().await.unwrap().expect("a newer release");
    assert_eq!(update.version, ANNOUNCED_VERSION);
    assert_eq!(update.current_version, CURRENT_VERSION);
    assert_eq!(update.body.as_deref(), Some("local fixture release"));
    assert_eq!(
        update.download_url.as_str(),
        format!("{}/artifact", feed.base)
    );

    // The endpoint template resolved: the feed saw the platform path the
    // release config's shape names, with the current version in it.
    let path = requests_of(&feed).first().unwrap().clone();
    let expected = format!(
        "/desktop/test/{}/{}/{}",
        os_name(),
        arch_name(),
        CURRENT_VERSION
    );
    assert_eq!(path, expected, "the endpoint template resolved");

    // Download verifies and returns the artifact: chunks reported, the
    // total said once, the bytes exactly what the feed served.
    let mut progress = Vec::new();
    let mut finished = false;
    let bytes = update
        .download(
            |chunk, total| progress.push((chunk, total)),
            || finished = true,
        )
        .await
        .expect("the artifact downloads");
    assert_eq!(bytes, ARTIFACT);
    assert!(finished, "the download-finished hook ran");
    assert_eq!(
        progress.iter().map(|(c, _)| c).sum::<usize>(),
        ARTIFACT.len()
    );
    assert_eq!(progress.first().unwrap().1, Some(ARTIFACT.len() as u64));
}

#[tokio::test]
async fn an_older_release_is_not_an_update() {
    let feed = Feed::start().await;
    *feed.version.lock().unwrap() = "0.0.9".to_string();
    let app = mock_app();
    let updater = updater_on(&app, &feed);
    assert!(updater.check().await.unwrap().is_none());
}

#[tokio::test]
async fn tampered_bytes_are_refused() {
    let feed = Feed::start().await;
    let mut tampered = ARTIFACT.to_vec();
    let last = tampered.len() - 1;
    tampered[last] ^= 0x01;
    *feed.artifact.lock().unwrap() = tampered;
    let app = mock_app();
    let updater = updater_on(&app, &feed);

    let update = updater.check().await.unwrap().expect("still offered");
    let err = update
        .download(|_, _| {}, || {})
        .await
        .expect_err("tampered bytes are refused");
    assert!(
        err.to_string().contains("signature"),
        "the refusal names the signature: {err}"
    );
}

#[tokio::test]
async fn an_artifact_signed_by_another_publisher_is_refused() {
    let feed = Feed::start().await;
    // The manifest itself is plain JSON and unsigned: another publisher's
    // feed answers the check just fine...
    *feed.signature.lock().unwrap() = OTHER_SIGNATURE.to_string();
    let app = mock_app();
    let updater = updater_on(&app, &feed);
    let update = updater
        .check()
        .await
        .unwrap()
        .expect("the manifest answers");
    // ...and it is the signature check that stops the artifact.
    let err = update
        .download(|_, _| {}, || {})
        .await
        .expect_err("a foreign key is refused");
    assert!(
        err.to_string().contains("signature"),
        "the refusal names the signature: {err}"
    );
}
